#!/usr/bin/env python3
"""Validation script for pipeline outputs."""

import json
import os
import sys

try:
    import pandas as pd
except ImportError:
    print("pandas is required. Please install it: pip install pandas")
    sys.exit(1)


def check_file_exists_and_not_empty(filepath):
    """Check if a file exists and is not empty."""
    if not os.path.exists(filepath):
        return False, f"File does not exist: {filepath}"
    if os.path.getsize(filepath) == 0:
        return False, f"File is empty: {filepath}"
    return True, f"File exists and is not empty: {filepath}"


def check_csv_structure(filepath, expected_columns, expected_rows=None):
    """Validate CSV file structure."""
    if not os.path.exists(filepath):
        return False, f"File does not exist: {filepath}"

    try:
        df = pd.read_csv(filepath)
    except Exception as e:
        return False, f"Error reading CSV: {str(e)}"

    if df.empty:
        return False, f"CSV file is empty: {filepath}"

    # Check expected columns
    if expected_columns:
        missing_cols = [col for col in expected_columns if col not in df.columns]
        if missing_cols:
            return False, f"Missing columns in {filepath}: {missing_cols}. Found: {list(df.columns)}"

    # Check expected rows
    if expected_rows is not None and len(df) != expected_rows:
        return False, f"Expected {expected_rows} rows in {filepath}, got {len(df)}"

    return True, f"CSV structure valid: {len(df)} rows x {len(df.columns)} columns in {filepath}"


def check_csv_has_rows(filepath):
    """Check that a CSV file has at least one row of data."""
    if not os.path.exists(filepath):
        return False, f"File does not exist: {filepath}"
    try:
        df = pd.read_csv(filepath)
    except Exception as e:
        return False, f"Error reading CSV: {str(e)}"

    if df.empty:
        return False, f"CSV file is empty: {filepath}"
    return True, f"File has {len(df)} rows and {len(df.columns)} columns"


def validate_t01_selected_indicators():
    """Validate outputs/t01_selected_indicators.csv"""
    filepath = "outputs/t01_selected_indicators.csv"
    checks = []

    checks.append({
        "check_name": "t01_file_exists_and_not_empty",
        "passed": os.path.exists(filepath) and os.path.getsize(filepath) > 0,
        "message": "File exists and is not empty" if (os.path.exists(filepath) and os.path.getsize(filepath) > 0)
                   else f"File missing or empty: {filepath}"
    })

    passed, msg = check_csv_structure(
        filepath,
        expected_columns=["indicator_id", "indicator_name", "theme", "justification", "expected_direction"],
        expected_rows=12
    )
    checks.append({
        "check_name": "t01_correct_structure",
        "passed": passed,
        "message": msg
    })

    return checks


def validate_t05_clean_stops():
    """Validate outputs/t05_clean_stops.csv"""
    filepath = "outputs/t05_clean_stops.csv"
    checks = []

    checks.append({
        "check_name": "t05_file_exists_and_not_empty",
        "passed": os.path.exists(filepath) and os.path.getsize(filepath) > 0,
        "message": "File exists and is not empty" if (os.path.exists(filepath) and os.path.getsize(filepath) > 0)
                   else f"File missing or empty: {filepath}"
    })

    passed, msg = check_csv_structure(
        filepath,
        expected_columns=["stop_id", "stop_name", "stop_lat", "stop_lon"],
        expected_rows=407
    )
    checks.append({
        "check_name": "t05_correct_structure",
        "passed": passed,
        "message": msg
    })

    return checks


def validate_t08_pois_clean():
    """Validate outputs/t08_pois_clean.csv"""
    filepath = "outputs/t08_pois_clean.csv"
    checks = []

    checks.append({
        "check_name": "t08_file_exists_and_not_empty",
        "passed": os.path.exists(filepath) and os.path.getsize(filepath) > 0,
        "message": "File exists and is not empty" if (os.path.exists(filepath) and os.path.getsize(filepath) > 0)
                   else f"File missing or empty: {filepath}"
    })

    passed, msg = check_csv_structure(
        filepath,
        expected_columns=["qid", "label", "poi_type", "latitude", "longitude", "source"],
        expected_rows=48
    )
    checks.append({
        "check_name": "t08_correct_structure",
        "passed": passed,
        "message": msg
    })

    return checks


def validate_t10_accessibility_scores():
    """Validate outputs/t10_accessibility_scores.csv"""
    filepath = "outputs/t10_accessibility_scores.csv"
    checks = []

    checks.append({
        "check_name": "t10_file_exists_and_not_empty",
        "passed": os.path.exists(filepath) and os.path.getsize(filepath) > 0,
        "message": "File exists and is not empty" if (os.path.exists(filepath) and os.path.getsize(filepath) > 0)
                   else f"File missing or empty: {filepath}"
    })

    passed, msg = check_csv_structure(
        filepath,
        expected_columns=["qid", "label", "poi_type", "distance_m", "n_departures", "n_routes", "accessibility_score"],
        expected_rows=48
    )
    checks.append({
        "check_name": "t10_correct_structure",
        "passed": passed,
        "message": msg
    })

    return checks


def validate_t13_city_clusters():
    """Validate outputs/t13_city_clusters.csv"""
    filepath = "outputs/t13_city_clusters.csv"
    checks = []

    checks.append({
        "check_name": "t13_file_exists_and_not_empty",
        "passed": os.path.exists(filepath) and os.path.getsize(filepath) > 0,
        "message": "File exists and is not empty" if (os.path.exists(filepath) and os.path.getsize(filepath) > 0)
                   else f"File missing or empty: {filepath}"
    })

    passed, msg = check_csv_has_rows(filepath)
    checks.append({
        "check_name": "t13_has_data",
        "passed": passed,
        "message": msg
    })

    return checks


def main():
    """Run all validation checks."""
    validation_results = []

    # Validate each output file
    validation_results.extend(validate_t01_selected_indicators())
    validation_results.extend(validate_t05_clean_stops())
    validation_results.extend(validate_t08_pois_clean())
    validation_results.extend(validate_t10_accessibility_scores())
    validation_results.extend(validate_t13_city_clusters())

    # Write validation summary
    output_path = "outputs/t14_validation_summary.json"
    os.makedirs("outputs", exist_ok=True)

    with open(output_path, "w") as f:
        json.dump(validation_results, f, indent=2)

    # Print summary
    passed = sum(1 for check in validation_results if check["passed"])
    total = len(validation_results)
    print(f"Validation complete: {passed}/{total} checks passed")

    if passed < total:
        print("Some checks failed:")
        for check in validation_results:
            if not check["passed"]:
                print(f"  - {check['check_name']}: {check['message']}")
        sys.exit(1)
    else:
        print("All checks passed!")
        sys.exit(0)


if __name__ == "__main__":
    main()
